#include <memory>
#include <vector>
#include <iostream>

struct MyObject {
    int value;
    MyObject(int v) : value(v) { std::cout << "Constructed " << v << std::endl; }
    ~MyObject() { std::cout << "Destroyed " << value << std::endl; }
};

int main() {
    // Allocate raw memory for 3 MyObject instances
    std::unique_ptr<char[]> buffer(new char[3 * sizeof(MyObject)]);
    MyObject* raw_memory = reinterpret_cast<MyObject*>(buffer.get());

    // Use uninitialized_copy_n to construct objects in raw memory
    std::vector<int> values = {1, 2, 3};
    auto it = std::uninitialized_copy_n(values.begin(), values.size(), raw_memory);

    // Access constructed objects
    for (MyObject* ptr = raw_memory; ptr != it; ++ptr) {
        std::cout << "MyObject with value: " << ptr->value << std::endl;
    }

    // Manually destroy objects
    for (MyObject* ptr = raw_memory; ptr != it; ++ptr) {
        ptr->~MyObject();
    }
    return 0;
}
